<?php declare(strict_types=1); namespace App\Interface\Http\Review\Controller; use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Review\DTO\Request\RateFlashcardInputRequestDto;use App\Application\Review\DTO\Request\RateFlashcardRequestDto;use App\Application\Review\Mapper\FlashcardReviewResponseMapper;use App\Application\Review\Service\RateFlashcardService;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface; final class ReviewRatingController { public function __construct(private AuthService $auth,private RateFlashcardService $service,private FlashcardReviewResponseMapper $mapper,private ApiResponseFactory $responses){} public function rate(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,RateFlashcardInputRequestDto $input):ResponseInterface{try{$user=$this->auth->currentUser($access);$review=$this->service->execute(new RateFlashcardRequestDto($user->id,$input->sessionId,$input->flashcardId,$input->rating),new \DateTimeImmutable('now'));return $review===null?$this->responses->problem($p,'STATE_CONFLICT','Esta classificação já foi registrada.',409,(string)$r->getAttribute('request_id')):$this->responses->success($p,$this->mapper->map($review),(string)$r->getAttribute('request_id'));}catch(\InvalidArgumentException){return $this->responses->problem($p,'VALIDATION_FAILED','Classificação inválida.',422,(string)$r->getAttribute('request_id'));}catch(\DomainException){return $this->responses->problem($p,'RESOURCE_NOT_FOUND','Card de revisão não encontrado.',404,(string)$r->getAttribute('request_id'));}} }
